import serverUtils from "@mat3ra/utils/server";
import * as fs from "fs";
import * as path from "path";

import { BUILD_CONFIG } from "../../build-config";

/**
 * Combine the per-archive pseudopotential files generated by the `pseudos` repo
 * (assets/metaProperties/pseudopotentials/<source>_<type>_<functional>[_<version>].json)
 * into one runtime file keyed by collection name, so consumers load all of them with one import.
 */
const rootDir = path.resolve(__dirname, "../..");
const { assets, build } = BUILD_CONFIG.metaProperties;
const sourceDirectory = path.resolve(rootDir, assets.path, assets.pseudopotentials);
const outputFilename = `${assets.pseudopotentials}.json`;
const destinationPaths = [
    path.resolve(rootDir, build.path, outputFilename),
    path.resolve(rootDir, BUILD_CONFIG.distRuntimeDataDir, "metaProperties", outputFilename),
];

function readCollection(filename: string): unknown[] {
    const content = serverUtils.json.readJSONFileSync(path.join(sourceDirectory, filename));
    if (!Array.isArray(content)) {
        throw new Error(`Expected ${filename} to be a JSON array, got ${typeof content}`);
    }
    return content;
}

function readCollectionsByName(): Record<string, unknown[]> {
    if (!fs.existsSync(sourceDirectory)) {
        throw new Error(`Pseudopotential assets not found: ${sourceDirectory}`);
    }
    const filenames = fs
        .readdirSync(sourceDirectory)
        .filter((filename) => filename.endsWith(".json"))
        .sort();
    if (filenames.length === 0) {
        throw new Error(`No pseudopotential collections in ${sourceDirectory}`);
    }
    return Object.fromEntries(
        filenames.map((filename) => [path.basename(filename, ".json"), readCollection(filename)]),
    );
}

const collectionsByName = readCollectionsByName();

destinationPaths.forEach((destinationPath) => {
    serverUtils.file.createDirIfNotExistsSync(path.dirname(destinationPath));
    serverUtils.json.writeJSONFileSync(destinationPath, collectionsByName, {
        spaces: BUILD_CONFIG.buildJSONFormat.spaces,
    });
    console.log(`  Built: ${destinationPath}`);
});

const entryCount = Object.values(collectionsByName).reduce((sum, list) => sum + list.length, 0);
const collectionCount = Object.keys(collectionsByName).length;
console.log(
    `✅ metaProperties completed (${entryCount} pseudopotentials, ${collectionCount} collections).`,
);
